self.addEventListener("push",i=>{if(i.data)try{let t=i.data.json(),n=t.title||"Notifikasi Baru",o={body:t.body||"Ada pembaruan informasi dari MI Attaqwa 15.",icon:t.icon||"/icons/icon-192x192.png",badge:t.badge||"/icons/icon-192x192.png",vibrate:[100,50,100],data:{url:t.url||"/"}};i.waitUntil(self.registration.showNotification(n,o))}catch(t){console.error("Error parsing push notification data",t),i.waitUntil(self.registration.showNotification("Notifikasi MI Attaqwa 15",{body:i.data.text(),icon:"/icons/icon-192x192.png"}))}}),self.addEventListener("notificationclick",i=>{i.notification.close(),i.notification.data&&i.notification.data.url&&i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if(n.url.includes(i.notification.data.url)&&"focus"in n)return n.focus();if(self.clients.openWindow)return self.clients.openWindow(i.notification.data.url)}))});